    <script>
        class CoinRenderer {
            constructor(canvas) {
                this.canvas = canvas;
                this.ctx = canvas.getContext('2d');
                this.width = canvas.width = canvas.clientWidth;
                this.height = canvas.height = canvas.clientHeight;
                this.time = 0;
                this.isAnimating = true;
                this.lastTime = Date.now();
            }

            rotateX(point, angle) {
                const cos = Math.cos(angle);
                const sin = Math.sin(angle);
                return [
                    point[0],
                    point[1] * cos - point[2] * sin,
                    point[1] * sin + point[2] * cos
                ];
            }

            rotateY(point, angle) {
                const cos = Math.cos(angle);
                const sin = Math.sin(angle);
                return [
                    point[0] * cos + point[2] * sin,
                    point[1],
                    -point[0] * sin + point[2] * cos
                ];
            }

            rotateZ(point, angle) {
                const cos = Math.cos(angle);
                const sin = Math.sin(angle);
                return [
                    point[0] * cos - point[1] * sin,
                    point[0] * sin + point[1] * cos,
                    point[2]
                ];
            }

            project(point, distance = 4) {
                const z = point[2] + distance;
                const scale = 1.5 / z;
                return [
                    this.width / 2 + point[0] * scale * this.width / 2,
                    this.height / 2 - point[1] * scale * this.height / 2,
                    z,
                    scale
                ];
            }

            renderCoin(t) {
                this.ctx.fillStyle = 'rgba(10,10,16,1)';
                this.ctx.fillRect(0, 0, this.width, this.height);

                // Rotation angles
                const rotY = t * Math.PI * 2; // Spin around Y (vertical axis)
                const rotX = Math.sin(t * Math.PI * 2) * Math.PI * 0.35; // Flip around X (horizontal axis)

                // Generate coin geometry - cylinder with embossed faces
                const segments = 80;
                const rings = 32;
                const radius = 1.0;
                const thickness = 0.25;

                const rings3d = [];
                const faceIndices = [];

                // Create 3D vertex rings
                for (let ring = 0; ring <= rings; ring++) {
                    const v = (ring / rings - 0.5) * thickness;
                    const ringVerts = [];

                    for (let seg = 0; seg < segments; seg++) {
                        const u = seg / segments;
                        const angle = u * Math.PI * 2;

                        let x = Math.cos(angle) * radius;
                        let y = Math.sin(angle) * radius;
                        let z = v;

                        // Emboss based on distance from center (front face effect)
                        const dist = Math.sqrt(x * x + y * y);
                        const emboss = Math.pow(Math.max(0, 1 - dist), 2) * 0.15;

                        if (v > 0) {
                            z += emboss; // Front face protrudes
                        } else {
                            z -= emboss * 0.5; // Back face slight depression
                        }

                        // Apply rotations
                        let pt = [x, y, z];
                        pt = this.rotateX(pt, rotX);
                        pt = this.rotateY(pt, rotY);

                        const proj = this.project(pt);
                        ringVerts.push({
                            x: pt[0], y: pt[1], z: pt[2],
                            px: proj[0], py: proj[1], pz: proj[2], scale: proj[3],
                            u: u, v: (ring / rings - 0.5), angle: angle, 
                            localZ: v, localDist: dist
                        });
                    }
                    rings3d.push(ringVerts);
                }

                // Sort rings by depth for proper drawing order
                const depthMap = [];
                for (let ring = 0; ring < rings3d.length; ring++) {
                    let avgZ = 0;
                    for (let v of rings3d[ring]) avgZ += v.pz;
                    depthMap.push({ring, avgZ: avgZ / rings3d[ring].length});
                }
                depthMap.sort((a, b) => a.avgZ - b.avgZ);

                // Draw coin faces and edges
                for (let {ring} of depthMap) {
                    if (ring === 0 || ring === rings3d.length - 1) continue;

                    const r1 = rings3d[ring];
                    const r2 = rings3d[ring + 1];

                    for (let seg = 0; seg < segments; seg++) {
                        const v1 = r1[seg];
                        const v2 = r1[(seg + 1) % segments];
                        const v3 = r2[(seg + 1) % segments];
                        const v4 = r2[seg];

                        // Calculate normal and lighting
                        const dx1 = v2.x - v1.x;
                        const dy1 = v2.y - v1.y;
                        const dz1 = v2.z - v1.z;
                        const dx2 = v4.x - v1.x;
                        const dy2 = v4.y - v1.y;
                        const dz2 = v4.z - v1.z;

                        const nx = dy1 * dz2 - dz1 * dy2;
                        const ny = dz1 * dx2 - dx1 * dz2;
                        const nz = dx1 * dy2 - dy1 * dx2;
                        const nlen = Math.sqrt(nx*nx + ny*ny + nz*nz);

                        if (nlen === 0) continue;

                        const nnx = nx / nlen;
                        const nny = ny / nlen;
                        const nnz = nz / nlen;

                        // Lighting: directional + specular
                        const lightDir = [0.6, 0.5, 0.8];
                        const lightLen = Math.sqrt(lightDir[0]*lightDir[0] + lightDir[1]*lightDir[1] + lightDir[2]*lightDir[2]);
                        const lx = lightDir[0] / lightLen;
                        const ly = lightDir[1] / lightLen;
                        const lz = lightDir[2] / lightLen;

                        const diff = Math.max(0, nnx * lx + nny * ly + nnz * lz);

                        // Specular highlight
                        const viewDir = [0, 0, -1];
                        const reflX = 2 * (nnx * lx + nny * ly + nnz * lz) * nnx - lx;
                        const reflY = 2 * (nnx * lx + nny * ly + nnz * lz) * nny - ly;
                        const reflZ = 2 * (nnx * lx + nny * ly + nnz * lz) * nnz - lz;

                        const spec = Math.max(0, reflX * viewDir[0] + reflY * viewDir[1] + reflZ * viewDir[2]);
                        const specular = Math.pow(spec, 30);

                        // Metallic color based on face
                        let r, g, b;
                        if (v1.localZ > 0) {
                            // Front face - gold tone
                            r = 220 + diff * 35 + specular * 100;
                            g = 180 + diff * 35 + specular * 100;
                            b = 80 + diff * 35 + specular * 80;
                        } else {
                            // Back face - slightly different tone
                            r = 200 + diff * 40 + specular * 100;
                            g = 190 + diff * 40 + specular * 100;
                            b = 140 + diff * 40 + specular * 80;
                        }

                        r = Math.min(255, r);
                        g = Math.min(255, g);
                        b = Math.min(255, b);

                        this.ctx.fillStyle = `rgb(${Math.floor(r)},${Math.floor(g)},${Math.floor(b)})`;

                        this.ctx.beginPath();
                        this.ctx.moveTo(v1.px, v1.py);
                        this.ctx.lineTo(v2.px, v2.py);
                        this.ctx.lineTo(v3.px, v3.py);
                        this.ctx.lineTo(v4.px, v4.py);
                        this.ctx.fill();
                    }
                }

                // Draw reeded edge
                const edgeRing = Math.floor(rings / 2);
                const edge = rings3d[edgeRing];

                this.ctx.strokeStyle = 'rgba(255,255,255,0.3)';
                this.ctx.lineWidth = 1;

                for (let seg = 0; seg < segments; seg += 3) {
                    const v = edge[seg];
                    const nx = Math.cos(v.angle);
                    const ny = Math.sin(v.angle);

                    const ext = 0.15;
                    const pt2 = this.project([v.x + nx * ext, v.y + ny * ext, v.z]);

                    this.ctx.beginPath();
                    this.ctx.moveTo(v.px, v.py);
                    this.ctx.lineTo(pt2[0], pt2[1]);
                    this.ctx.stroke();
                }

                // Draw face text
                const topZ = rings3d[rings][Math.floor(segments/4)];
                const topProj = this.project([0, 0, thickness/2 + 0.15]);

                this.ctx.fillStyle = 'rgba(0,0,0,0.6)';
                this.ctx.font = 'bold 20px sans-serif';
                this.ctx.textAlign = 'center';
                this.ctx.textBaseline = 'middle';

                const cosRot = Math.cos(rotY);
                const sinRot = Math.sin(rotY);

                if (Math.abs(cosRot) > 0.3) {
                    if (cosRot > 0) {
                        this.ctx.fillText('⚔ WASTED ⚔', this.width/2, this.height/2 - 30);
                        this.ctx.fillText('TOKEN MINT', this.width/2, this.height/2 + 30);
                    } else {
                        this.ctx.fillText('10,000', this.width/2, this.height/2 - 20);
                        this.ctx.fillText('TOKENS', this.width/2, this.height/2 + 20);
                    }
                }
            }

            setTime(t) {
                this.time = Math.max(0, Math.min(1, t));
                this.renderCoin(this.time);
            }

            pause() {
                this.isAnimating = false;
            }

            animate() {
                if (this.isAnimating) {
                    const now = Date.now();
                    const dt = (now - this.lastTime) / 1000;
                    this.lastTime = now;

                    this.time += dt * 0.5;
                    if (this.time > 1) this.time -= 1;

                    this.renderCoin(this.time);
                }
                requestAnimationFrame(() => this.animate());
            }
        }

        // Initialize hero coin
        const heroCanvas = document.getElementById('coin-hero');
        const coinRenderer = new CoinRenderer(heroCanvas);
        coinRenderer.animate();

        // Expose demo API
        window.demo = {
            canvas: heroCanvas,
            setTime: (t) => coinRenderer.setTime(t),
            pause: () => coinRenderer.pause()
        };

        // Render edition coins
        function drawEditionCoin(canvas, metalColor, title, value) {
            const ctx = canvas.getContext('2d');
            const w = canvas.width = canvas.clientWidth;
            const h = canvas.height = canvas.clientHeight;
            const cx = w / 2;
            const cy = h / 2;
            const r = Math.min(w, h) * 0.32;

            const bgGrad = ctx.createRadialGradient(cx*0.6, cy*0.6, 0, cx, cy, r*1.8);
            bgGrad.addColorStop(0, '#1a1a2e');
            bgGrad.addColorStop(1, '#0a0a0a');
            ctx.fillStyle = bgGrad;
            ctx.fillRect(0, 0, w, h);

            // Coin
            const coinGrad = ctx.createRadialGradient(cx*0.8, cy*0.8, r*0.1, cx, cy, r*1.2);
            coinGrad.addColorStop(0, metalColor[2]);
            coinGrad.addColorStop(0.5, metalColor[0]);
            coinGrad.addColorStop(1, metalColor[1]);

            ctx.fillStyle = coinGrad;
            ctx.beginPath();
            ctx.arc(cx, cy, r, 0, Math.PI * 2);
            ctx.fill();

            // Highlight
            const hlGrad = ctx.createRadialGradient(cx-r*0.3, cy-r*0.3, r*0.05, cx+r*0.2, cy+r*0.2, r*0.8);
            hlGrad.addColorStop(0, 'rgba(255,255,255,0.4)');
            hlGrad.addColorStop(1, 'rgba(255,255,255,0)');
            ctx.fillStyle = hlGrad;
            ctx.beginPath();
            ctx.arc(cx, cy, r, 0, Math.PI * 2);
            ctx.fill();

            // Rim
            ctx.strokeStyle = 'rgba(0,0,0,0.4)';
            ctx.lineWidth = 3;
            ctx.stroke();

            // Reeded edge
            ctx.strokeStyle = 'rgba(255,255,255,0.2)';
            ctx.lineWidth = 1;
            for (let i = 0; i < 20; i++) {
                const a = (i / 20) * Math.PI * 2;
                const x1 = cx + Math.cos(a) * r;
                const y1 = cy + Math.sin(a) * r;
                const x2 = cx + Math.cos(a) * (r + 4);
                const y2 = cy + Math.sin(a) * (r + 4);
                ctx.beginPath();
                ctx.moveTo(x1, y1);
                ctx.lineTo(x2, y2);
                ctx.stroke();
            }

            // Text
            ctx.fillStyle = metalColor[3];
            ctx.font = 'bold 12px sans-serif';
            ctx.textAlign = 'center';
            ctx.textBaseline = 'middle';
            ctx.fillText(title, cx, cy - 8);
            ctx.fillText(value, cx, cy + 10);
        }

        const editionConfigs = [
            { el: '[data-edition="bronze"]', color: ['#d4a574', '#b8860b', '#8b4513', '#8b6914'], title: 'BRONZE', value: '5K TOKENS' },
            { el: '[data-edition="silver"]', color: ['#e8e8e8', '#c0c0c0', '#808080', '#f0f0f0'], title: 'SILVER', value: '7.5K TOKENS' },
            { el: '[data-edition="gold"]', color: ['#ffd700', '#daa520', '#b8860b', '#ffed4e'], title: 'GOLD', value: '10K TOKENS' },
            { el: '[data-edition="black"]', color: ['#1a1a1a', '#333333', '#0a0a0a', '#555555'], title: 'OBSIDIAN', value: '15K TOKENS' }
        ];

        editionConfigs.forEach(cfg => {
            const el = document.querySelector(cfg.el);
            const canvas = el.querySelector('.edition-canvas');
            drawEditionCoin(canvas, cfg.color, cfg.title, cfg.value);
        });

        // Disable sold-out and coming-soon buttons
        document.querySelectorAll('[data-state="sold-out"], [data-state="coming-soon"]').forEach(el => {
            const btn = el.querySelector('.buy');
            if (btn) btn.disabled = true;
        });

        // Cart functionality
        document.querySelectorAll('.buy:not(:disabled)').forEach(btn => {
            btn.addEventListener('click', () => {
                alert('Added to cart! (Demo checkout)');
            });
        });
    </script>
